INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Besteht der DHCP-Prozess aus den Schritten Discover, Offer, Request, Acknowledge?', 2, '[{"text": "Ja", "correct": true, "because": "DORA ist der Standardprozess"}, {"text": "Nein", "correct": false, "because": "Korrekte Abfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt startet den DHCP-Prozess?', 3, '[{"text": "Discover", "correct": true, "because": "Client sucht Server"}, {"text": "Offer", "correct": false, "because": "Antwort des Servers"}, {"text": "Request", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Offer kommt vom Server. b) Acknowledge ist der erste Schritt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Acknowledge ist letzter Schritt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim DHCP-Prozess?', 4, '[{"text": "Discover-Nachricht", "correct": false, "because": "Startet Prozess"}, {"text": "Acknowledge-Bestätigung", "correct": false, "because": "Schließt Prozess ab"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Client bei Discover eine IP-Adresse hat?', 2, '[{"text": "Nein", "correct": true, "because": "Client sucht erst eine IP"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert im Offer-Schritt?', 3, '[{"text": "Server bietet IP an", "correct": true, "because": "Antwort auf Discover"}, {"text": "Client bestätigt IP", "correct": false, "because": "Das ist Request"}, {"text": "Server sucht Client", "correct": false, "because": "Umgekehrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum DHCP-Prozess?', 5, '[{"text": "Discover", "correct": true, "because": "Clientanfrage"}, {"text": "Offer", "correct": true, "because": "Serverangebot"}, {"text": "Request", "correct": true, "because": "Clientanforderung"}, {"text": "Acknowledge", "correct": true, "because": "Serverbestätigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Request kommt nach Offer. b) Discover ist die Serverantwort. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Discover ist Clientanfrage"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den DHCP-Prozess?', 4, '[{"text": "Clientanfrage", "correct": false, "because": "Startet mit Discover"}, {"text": "Serverantwort", "correct": false, "because": "Offer und Acknowledge"}, {"text": "Manuelle IP-Eingabe", "correct": true, "because": "Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Acknowledge der letzte Schritt im DHCP-Prozess?', 2, '[{"text": "Ja", "correct": true, "because": "Bestätigt die IP-Vergabe"}, {"text": "Nein", "correct": false, "because": "Korrekte Abfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht folgt auf Request im DHCP-Prozess?', 4, '[{"text": "Acknowledge", "correct": true, "because": "Server bestätigt Anforderung"}, {"text": "Offer", "correct": false, "because": "Vor Request"}, {"text": "Discover", "correct": false, "because": "Erster Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Offer der letzte Schritt ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Request und Acknowledge folgen"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im DHCP-Prozess?', 3, '[{"text": "Reihenfolge DORA", "correct": true, "because": "Sichert korrekte Vergabe"}, {"text": "Schnelligkeit", "correct": false, "because": "Korrektheit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Discover ist ein Broadcast. b) Request kommt vom Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Request ist Clientanfrage"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen spielen Client und Server im DHCP-Prozess?', 5, '[{"text": "Client sendet Discover", "correct": true, "because": "Startet Prozess"}, {"text": "Server sendet Offer", "correct": true, "because": "Bietet IP an"}, {"text": "Client sendet Request", "correct": true, "because": "Fordert IP an"}, {"text": "Server sendet Acknowledge", "correct": true, "because": "Bestätigt Vergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im DHCP-Prozess unwichtig?', 3, '[{"text": "Broadcast-Nachrichten", "correct": false, "because": "Für Discover und Offer"}, {"text": "Client-Server-Kommunikation", "correct": false, "because": "Kern des Prozesses"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sendet der Client bei Request einen Broadcast?', 3, '[{"text": "Ja", "correct": true, "because": "Erreicht alle Server"}, {"text": "Nein", "correct": false, "because": "Korrekte Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Offer mehrere IP-Adressen vorschlägt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur eine IP pro Offer"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht bestätigt die IP-Zuweisung im DHCP-Prozess?', 4, '[{"text": "Acknowledge", "correct": true, "because": "Letzter Schritt"}, {"text": "Discover", "correct": false, "because": "Erster Schritt"}, {"text": "Offer", "correct": false, "because": "Zweiter Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt folgt auf Discover?', 3, '[{"text": "Offer", "correct": true, "because": "Server antwortet"}, {"text": "Request", "correct": false, "because": "Dritter Schritt"}, {"text": "Acknowledge", "correct": false, "because": "Letzter Schritt"}]');
